import from "node:fs/promises" { default as fs }
import from "node:path" { default as path }

glob process: any;

def getFontPath(fontName: str) -> any {
    return process.cwd().join(path);
}

async def getRegularFont() -> any {
    response = await fs.readFile(getFontPath("Geist-Regular.otf"));
    font = new(Uint8Array, response).buffer;
    return font;
}

async def getMediumFont() -> any {
    response = await fs.readFile(getFontPath("Geist-Medium.otf"));
    font = new(Uint8Array, response).buffer;
    return font;
}

async def getSemiBoldFont() -> any {
    response = await fs.readFile(getFontPath("Geist-SemiBold.otf"));
    font = new(Uint8Array, response).buffer;
    return font;
}

async def:pub getOGImageFonts() -> list {
    regularFontData = await getRegularFont();
    mediumFontData = await getMediumFont();
    semiBoldFontData = await getSemiBoldFont();

    return [
        {"name": "Geist Sans", "data": regularFontData, "style": "normal", "weight": 400},
        {"name": "Geist Sans", "data": mediumFontData, "style": "normal", "weight": 500},
        {"name": "Geist Sans", "data": semiBoldFontData, "style": "normal", "weight": 600}
    ];
}
